    try:
        if not (2000 <= y <= 2035):
            return False
        if not (1 <= m <= 12):
            return False
        if not (1 <= d <= 31):
            return False
        import datetime
        datetime.date(y, m, d)
        return True
    except Exception:
        return False


def _score_date_candidate(line_idx, line_text, total_lines, labeled):
    score = 0
    if labeled:
        score += 100
    if line_idx < total_lines * 0.5:
        score += 20
    if line_idx < total_lines * 0.3:
