    if s is None:
        return None
    s = str(s).strip()
    if not s:
        return None
    s = s.replace("RM", "").replace("rm", "").replace("$", "").strip()
    s = s.replace(" ", "").replace(",", "")
    s = re.sub(r"(\d)[:;](\d{2})\b", r"\1.\2", s)
    s = s.rstrip("-+.")
